  background-size: cover, 300px 200px !important;
  animation: lofiCloudScroll 28s linear infinite !important;
}
.chat-markdown-codeblock {
  backdrop-filter: blur(16px) !important;
  background: rgba(26, 16, 36, 0.74) !important;
  border: 1px solid rgba(251, 113, 133, 0.22) !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35) !important;
}
[data-chat-header] {
  backdrop-filter: blur(14px) !important;
  background: rgba(18, 11, 27, 0.8) !important;
  border-bottom: 1px solid rgba(251, 113, 133, 0.16) !important;
}
